SOURCE='from replica import *\nSTOP=threading.Event();SECRET=None\n\ndef events():\n out=[]\n for l in (ROOT/\'events.jsonl\').read_text().splitlines():\n  try:out.append(json.loads(l))\n  except ValueError:pass\n return out\n\ndef auth_failed():\n if not (ROOT/\'auth-observation-start.json\').exists():return False\n cutoff=json.loads((ROOT/\'auth-observation-start.json\').read_text())[\'at\']\n found=next((x for x in events() if x.get(\'at\',\'\')>=cutoff and x.get(\'event\')==\'http_finish\' and (x.get(\'status\')==401 or x.get(\'invalid_credentials\') or x.get(\'ErrInvalidOauthToken\'))),None)\n if found:\n  if not (ROOT/\'first-auth-failure.json\').exists():save(\'first-auth-failure.json\',found);emit(\'first_auth_failure\',evidence=found)\n  STOP.set()\n return bool(found)\n\ndef tokenmeta(t):\n try:\n  p=t.split(\'.\')[1];c=json.loads(base64.urlsafe_b64decode(p+\'=\'*(-len(p)%4)))\n except Exception:c={}\n return {\'sha256\':sha(t),\'sid_sha256\':sha(c.get(\'sid\',\'\')),\'user_id_sha256\':sha(c.get(\'user_id\',\'\')),\'exp\':c.get(\'exp\'),\'iat\':c.get(\'iat\')}\n\ndef login():\n assert not (ROOT/\'login-started.json\').exists(),\'authentication not replayable\'\n a=crows("SELECT json_build_object(\'proxy\',to_jsonb(p)) FROM accounts a JOIN proxies p ON p.id=a.proxy_id WHERE a.id=1738")[0][\'proxy\']\n auth=(urllib.parse.quote(a.get(\'username\') or \'\',safe=\'\')+\':\'+urllib.parse.quote(a.get(\'password\') or \'\',safe=\'\')+\'@\') if a.get(\'username\') else \'\'\n proxy=a[\'protocol\']+\'://\'+auth+a[\'host\']+\':\'+str(a[\'port\'])\n cfg={\'account_id\':1738,\'member_id\':1138,\'email\':\'CrawfordHeather6275@hotmail.com\',\'proxy\':proxy}\n save(\'login-started.json\',{\'at\':now(),\'mode\':\'production_direct_login\',\'account_id\':1738})\n cmd=[\'docker\',\'run\',\'--rm\',\'-i\',\'--name\',LOGIN,\'--network\',\'adobe-relay_default\',\'--memory\',\'768m\',\'--cpus\',\'1\',\'--read-only\',\'--tmpfs\',\'/tmp:rw,size=128m\',\'--mount\',f\'type=bind,src={ROOT},dst=/experiment,readonly\',\'--mount\',\'type=bind,src=/opt/adobe-team-cookie/data,dst=/app/data\',\'-e\',\'DATABASE_URL=sqlite:////app/data/app.db\',\'--entrypoint\',\'python\',OKAD,\'/experiment/login_isolated.py\']\n r=subprocess.run(cmd,input=json.dumps(cfg),text=True,capture_output=True,timeout=350)\n results=[x[len(\'PRIVATE_RESULT:\'):] for x in r.stdout.splitlines() if x.startswith(\'PRIVATE_RESULT:\')]\n assert results,\'isolated_login_no_result\'\n d=json.loads(results[-1]);record=d.get(\'record\') or {}\n safe={k:d.get(k) for k in [\'ok\',\'code\',\'events\',\'account_id\',\'error_class\',\'frames\',\'login_completed_at\',\'login_egress_sha256\',\'generation_egress_sha256\']};safe[\'record_keys\']=sorted(record);safe[\'token\']=tokenmeta(record.get(\'access_token\',\'\'));safe[\'cookie_sha256\']=sha(record.get(\'cookie\',\'\'));save(\'login-result.json\',safe)\n assert d.get(\'ok\') and record.get(\'cookie\'),\'isolated_login_failed\'\n # Only the Cookie crosses the real Sub2 integration endpoint. The login Token is deliberately not injected.\n data={\'email\':cfg[\'email\'],\'issuer\':SECRET[\'issuer\'],\'source_key\':\'external:1138\',\'version\':SECRET[\'version\'],\'cookie\':record[\'cookie\']}\n save(\'auth-observation-start.json\',{\'at\':now(),\'phase\':\'fresh_cookie_push\'})\n status,raw=request(\'POST\',\'/api/v1/integrations/okad/accounts/1738/credentials\',data,{\'X-API-Key\':SECRET[\'integration_key\']},timeout=35)\n emit(\'credential_push\',status=status,version=SECRET[\'version\'],cookie_sha256=sha(record[\'cookie\']))\n assert status==200,\'credential_push_failed\'\n status,raw=request(\'POST\',\'/api/v1/integrations/okad/accounts/1738/verify\',{}, {\'X-API-Key\':SECRET[\'integration_key\']},timeout=150)\n emit(\'initial_verification\',status=status,selected=selected())\n # Native connection-check queue runs its real Flare test and restores scheduling on success.\n deadline=time.time()+360\n while time.time()<deadline:\n  a=selected();save(\'latest-state.json\',a)\n  if auth_failed():return False\n  if a[\'status\']==\'active\' and a[\'schedulable\'] and (a.get(\'test\') or {}).get(\'state\')==\'success\':return True\n  time.sleep(3)\n emit(\'verification_not_ready\',selected=selected());return False\n\ndef test_png():\n # Deterministic engineering fixture: simple colored square, no user content.\n w=h=1024;rows=[]\n for y in range(h):rows.append(b\'\\x00\'+b\'\'.join((b\'\\xdc\\x32\\x32\' if 300<x<724 and 300<y<724 else b\'\\xf2\\xf2\\xf2\') for x in range(w)))\n def chunk(t,b):return struct.pack(\'!I\',len(b))+t+b+struct.pack(\'!I\',zlib.crc32(t+b)&0xffffffff)\n return b\'\\x89PNG\\r\\n\\x1a\\n\'+chunk(b\'IHDR\',struct.pack(\'!IIBBBBB\',w,h,8,2,0,0,0))+chunk(b\'IDAT\',zlib.compress(b\'\'.join(rows)))+chunk(b\'IEND\',b\'\')\nPNG=None\n\ndef one(job,model,offset,start):\n while time.time()<start+offset:\n  if STOP.wait(min(0.25,max(0,start+offset-time.time()))):return\n if STOP.is_set() or auth_failed():return\n rid=\'crawford-fullchain-\'+str(job);boundary=\'diag\'+secrets.token_hex(12)\n fields={\'model\':model,\'prompt\':\'Change the red square in the reference image to blue, keep the light background.\',\'size\':\'4096x4096\',\'n\':\'1\',\'response_format\':\'b64_json\'}\n body=b\'\'\n for k,v in fields.items():body+=(\'--\'+boundary+\'\\r\\nContent-Disposition: form-data; name="\'+k+\'"\\r\\n\\r\\n\'+v+\'\\r\\n\').encode()\n body+=(\'--\'+boundary+\'\\r\\nContent-Disposition: form-data; name="image"; filename="fixture.png"\\r\\nContent-Type: image/png\\r\\n\\r\\n\').encode()+PNG+(\'\\r\\n--\'+boundary+\'--\\r\\n\').encode()\n begin=time.monotonic();emit(\'business_start\',job=job,request_id=rid,model=model,size=\'4096x4096\',quality=\'omitted_default\',endpoint=\'/v1/images/edits\')\n try:\n  status,raw=request(\'POST\',\'/v1/images/edits\',body,{\'Authorization\':\'Bearer \'+SECRET[\'api_key\'],\'Content-Type\':\'multipart/form-data; boundary=\'+boundary,\'X-Request-ID\':rid},timeout=650)\n  try:d=json.loads(raw)\n  except ValueError:d={}\n  imgs=d.get(\'data\') or [];image_hashes=[]\n  if status==200:\n   for item in imgs:\n    if item.get(\'b64_json\'):\n     b=base64.b64decode(item[\'b64_json\']);image_hashes.append({\'bytes\':len(b),\'sha256\':sha(b)})\n  error=d.get(\'error\') or {};emit(\'business_finish\',job=job,status=status,model=model,duration_ms=round((time.monotonic()-begin)*1000),images=image_hashes,error_type=error.get(\'type\') if isinstance(error,dict) else None,error_code=error.get(\'code\') if isinstance(error,dict) else None)\n except Exception as e:emit(\'business_unknown\',job=job,error_class=type(e).__name__);STOP.set()\n auth_failed()\n\ndef export():\n save(\'database-journal.json\',crows(\'SELECT json_build_object(\\\'at\\\',at,\\\'old\\\',old_state,\\\'new\\\',new_state) FROM diag_account_journal_sha ORDER BY at\'))\n save(\'usage.json\',crows("SELECT json_build_object(\'at\',created_at,\'account_id\',account_id,\'model\',model,\'upstream_model\',upstream_model,\'request_id\',request_id,\'duration_ms\',duration_ms,\'image_count\',image_count,\'image_size\',image_size,\'image_input_size\',image_input_size,\'image_output_size\',image_output_size,\'image_size_source\',image_size_source,\'inbound_endpoint\',inbound_endpoint) FROM usage_logs ORDER BY created_at"))\n save(\'errors.json\',crows("SELECT json_build_object(\'at\',created_at,\'request_id\',request_id,\'client_request_id\',client_request_id,\'account_id\',account_id,\'model\',model,\'status\',status_code,\'upstream_status\',upstream_status_code,\'phase\',error_phase,\'invalid_credentials\',coalesce(upstream_error_message,\'\') LIKE \'%invalid_credentials%\',\'invalid_oauth_token\',coalesce(upstream_error_message,\'\') LIKE \'%ErrInvalidOauthToken%\') FROM ops_error_logs ORDER BY created_at"))\n save(\'route-events.json\',crows("SELECT json_build_object(\'at\',created_at,\'account_id\',account_id,\'from\',from_proxy_id,\'to\',to_proxy_id) FROM proxy_failover_events ORDER BY created_at"))\n save(\'final-state.json\',selected())\n\ndef monitor():\n while not STOP.wait(1):\n  try:\n   auth_failed();a=selected();save(\'latest-state.json\',a)\n   # Read-only watch: never alter the real production account.\n   r=prod("SELECT json_build_object(\'cookie\',md5(credentials->>\'cookie\'),\'runtime_cookie\',md5(credentials->>\'adobe_session_cookie\'),\'schedulable\',schedulable) FROM accounts WHERE id=1738")[0]\n   baseline_row=next(x for x in json.loads((ROOT/\'production-before.json\').read_text())[\'accounts_and_settings\'] if x.get(\'id\')==1738)\n   if r[\'cookie\']!=baseline_row[\'cookie\'] or r[\'runtime_cookie\']!=baseline_row[\'runtime_cookie\'] or r[\'schedulable\']:emit(\'production_selected_changed_abort\');STOP.set()\n  except Exception as e:emit(\'monitor_failure\',error_class=type(e).__name__);STOP.set()\n\nassert not (ROOT/\'trial-started.json\').exists(),\'do not repeat authentication or generation\'\nassert (ROOT/\'prepared.json\').exists() and not (ROOT/\'cleaned.json\').exists()\nSECRET=json.loads((PRIVATE/\'secrets.json\').read_text());save(\'trial-started.json\',{\'at\':now(),\'business_jobs_limit\':16,\'connection_check_queue_limit\':3,\'models\':[\'gpt-image-2.5-sunburst\',\'gpt-image-2.5-flare\'],\'initial_source\':\'production snapshot\',\'replica_only\':True})\ntry:\n ready=login()\n if ready:\n  PNG=test_png();thread=threading.Thread(target=monitor,daemon=True);thread.start()\n  for roundno in range(2):\n   if STOP.is_set():break\n   if roundno==1:\n    # Exercise a second real route using the normal admin update; automatic mode remains enabled.\n    choices=crows("SELECT json_build_object(\'id\',p.id) FROM proxies p JOIN proxy_failover_health h ON h.proxy_id=p.id WHERE p.deleted_at IS NULL AND p.status=\'active\' AND h.status=\'healthy\' AND h.checked_at>NOW()-INTERVAL \'3 minutes\' AND p.id<>1290 AND p.id<>(SELECT proxy_id FROM accounts WHERE id=1738) AND (SELECT count(*) FROM accounts a WHERE a.deleted_at IS NULL AND a.proxy_id=p.id)<3 AND NOT EXISTS(SELECT 1 FROM adobe_route_exclusions e WHERE e.proxy_id=p.id) AND NOT EXISTS(SELECT 1 FROM adobe_route_health rh WHERE rh.proxy_id=p.id AND rh.retry_after>NOW()) ORDER BY h.latency_ms,p.id LIMIT 1")\n    if choices:\n     previous=selected()[\'proxy_id\'];status,_=request(\'PUT\',\'/api/v1/admin/accounts/1738\',{\'proxy_id\':choices[0][\'id\'],\'manual_proxy_enabled\':False},{\'X-API-Key\':SECRET[\'admin_key\']},timeout=30);emit(\'controlled_route_change\',from_proxy_id=previous,to_proxy_id=choices[0][\'id\'],status=status,replica_only=True)\n    else:emit(\'second_route_unavailable\')\n   # Derived from the six production start times (18:14:48.354 through 18:14:59.904).\n   start=time.time()+ (25 if roundno==0 else 5);offsets=[0,1.912,5.198,9.180,10.798,11.550,15,18]\n   with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:\n    fut=[pool.submit(one,roundno*8+i+1,\'gpt-image-2.5-sunburst\' if i<6 else \'gpt-image-2.5-flare\',offsets[i],start) for i in range(8)]\n    for f in fut:f.result()\n   if not STOP.is_set():STOP.wait(60)\n  # Continue observing natural token/cache behavior after accepted work finishes.\n  if not STOP.is_set():STOP.wait(180)\n if auth_failed():\n  status,_=request(\'POST\',\'/api/v1/integrations/okad/accounts/1738/verify\',{}, {\'X-API-Key\':SECRET[\'integration_key\']},timeout=150)\n  emit(\'post_failure_verification\',status=status,selected=selected())\n export();save(\'trial-finished.json\',{\'at\':now(),\'auth_failure\':auth_failed(),\'selected\':selected()})\nexcept BaseException as e:\n import traceback\n save(\'trial-error.json\',{\'at\':now(),\'class\':type(e).__name__,\'message\':str(e) if str(e).startswith((\'isolated_\',\'credential_\',\'command_failed\')) else \'\', \'frames\':[{\'name\':x.name,\'line\':x.lineno} for x in traceback.extract_tb(e.__traceback__)]})\n try:export()\n except Exception:pass\nfinally:\n STOP.set();cleanup(\'trial_complete\')\n'
